std::set<std::string> seen_keys;
std::size_t object_count = 0;

Json::parser_callback_t callback =
    [&seen_keys, &object_count](int depth, Json::parse_event_t event, Json& parsed) -> bool {
        switch (event) {
            case Json::parse_event_t::array_start:
                if (depth != 0) {
                    throw std::invalid_argument("parse_ranking: nested array");
                }
                return true;
            case Json::parse_event_t::object_start:
                if (depth != 1) {
                    throw std::invalid_argument("parse_ranking: object outside row slot");
                }
                if (++object_count > kRankingLimit) {
                    throw std::invalid_argument("parse_ranking: too many rows");
                }
                seen_keys.clear();
                return true;
            case Json::parse_event_t::key:
                if (!seen_keys.insert(parsed.get<std::string>()).second) {
                    throw std::invalid_argument("parse_ranking: duplicate key");
                }
                return true;
            default:
                return true;
        }
    };

inline void ranking_route(httplib::Server& http,SqliteResults& store) {
    http.Get("/study/v1/ranking",[&store](const httplib::Request& req,httplib::Response& res) {
        res.set_header("Cache-Control","no-store");
        if(!req.params.empty() || !req.body.empty()) {
            res.status=400;res.set_content("{\"error\":\"invalid_request\"}","application/json");return;
        }
        try {res.set_content(ranking_json(store.ranking()).dump(),"application/json");}
        catch(const std::exception&) {
            res.status=503;res.set_content("{\"error\":\"ranking_unavailable\"}","application/json");
        }
    });
}

class RankingTask final {
public:
    explicit RankingTask(int port):port_(port){}
    std::optional<Ranking> operator()()const {
        if(port_<1 || port_>65535)return {};
        try {
            httplib::Client http("127.0.0.1",port_);
            http.set_connection_timeout(2,0);http.set_read_timeout(2,0);http.set_write_timeout(2,0);
            std::string body;
            const auto response=http.Get("/study/v1/ranking",[&](const char* bytes,std::size_t count) {
                if(count>kJsonBodyBytes-body.size())return false;
                body.append(bytes,count);return true;
            });
            if(!response || response->status!=200)return {};
            return parse_ranking(body);
        }catch(const std::exception&) {return {};}
    }
private:
    int port_;
};

template<class Worker>
class Job final {
public:
    using Result=std::invoke_result_t<Worker&>;
    explicit Job(std::unique_ptr<Worker> worker):worker_(std::move(worker)) {
        if(!worker_)throw std::invalid_argument("worker required");
    }
    Job(const Job&)=delete;
    Job& operator=(const Job&)=delete;
    bool valid()const {return future_.valid();}
    bool ready()const {
        return valid() && future_.wait_for(std::chrono::seconds(0))==std::future_status::ready;
    }
    bool start() {
        if(valid())return false;
        auto* worker=worker_.get();
        future_=std::async(std::launch::async,[worker]{return (*worker)();});
        return true;
    }
    Result take() {
        if(!ready())throw std::logic_error("job is not ready");
        return future_.get();
    }
private:
    std::unique_ptr<Worker> worker_;
    // Reverse destruction waits for the async job before destroying its Worker.
    std::future<Result> future_;
};

enum class Status {idle,busy,ready,failed};
struct View {Status status=Status::idle;study_meta::Ranking rows;};
// A successful empty list is ready; it is not a failed request.
template<class Worker>
class Controller final {
public:
    explicit Controller(std::unique_ptr<Worker> worker):job_(std::move(worker)){}
    const View& view()const {return view_;}
    bool busy()const {return job_.valid();}
    bool request() {
        if(busy())return false;
        try {
            if(!job_.start())return false;
            view_={Status::busy,{}};return true;
        }catch(const std::exception&) {view_={Status::failed,{}};return false;}
    }
    bool poll() {
        if(!job_.ready())return false;
        try {
            auto result=job_.take();
            view_=result && study_meta::valid_ranking(*result)
                ? View{Status::ready,std::move(*result)} : View{Status::failed,{}};
        }catch(const std::exception&) {view_={Status::failed,{}};}
        return true;
    }
private:
    View view_;
    study_jobs::Job<Worker> job_;
};

